# ---------- Lagebild aus dem Serverzustand ----------

def _body(robot: dict | None) -> Body:
    if not robot or not robot.get("center"):
        return Body()
    contour = robot.get("contour") or []
    return Body(bool(robot.get("present")), np.array(robot["center"], np.float32),
                np.array(robot.get("vel") or (0.0, 0.0), np.float32), float(robot.get("radius") or 40.0),
                np.array(contour, np.float32) if contour else None, float(robot.get("hp") or 0.0),
                float(robot.get("max_hp") or 0.0), bool(robot.get("outside")))


def snapshot_from(state: dict | None, slot: int, fresh: bool) -> Snapshot:
    if not state:
        return Snapshot("", 0, False, None, None, None, Body(), Body(), "nicht verfügbar", [])
    robots = {r["id"]: r for r in state.get("robots") or []}
    arena = state.get("arena")
    size = (float(arena["size"][0]), float(arena["size"][1])) if arena else None
    bounds = (0.0, 0.0, *size) if size else None
    zone = state.get("zone")
    if zone and size:
        xs, ys = [float(p[0]) for p in zone], [float(p[1]) for p in zone]
        bounds = (min(xs), min(ys), max(xs), max(ys))
    ulti = "nicht verfügbar"
    own = robots.get(slot)
    if own and own.get("ulti"):
        u = own["ulti"]
        ulti = ("verbraucht" if u.get("used") else "bereit" if u.get("ready")
                else f"lädt {round(100 * min(1.0, float(u.get('charge') or 0.0)))} %")
    items = []
    for item in state.get("items") or []:
        center = np.array(item["center"], np.float32)
        poly = np.array(item.get("poly") or [], np.float32)
        radius = float(np.linalg.norm(poly - center, axis=1).mean()) if len(poly) else 30.0
        items.append((item["kind"], center, radius))
    phase = state.get("phase", "")
    fighting = fresh and phase == "fight" and not state.get("finished")
    return Snapshot(phase, int(state.get("battle") or 0), fighting, state.get("elapsed"), size, bounds,
                    _body(own), _body(robots.get(3 - slot)), ulti, items)


def picture(snap: Snapshot, jpeg: bytes | None, frame: dict | None, angle: float | None,
            image_px: int) -> str | None:
    """Arenabild verkleinert und beschriftet, damit das Modell sich und den Gegner sicher erkennt."""
    if not jpeg or not frame or frame.get("kind") != "arena":
        return None
    img = cv2.imdecode(np.frombuffer(jpeg, np.uint8), cv2.IMREAD_COLOR)
    if img is None:
        return None
    w, h, pad = float(frame["w"]), float(frame["h"]), float(frame.get("pad") or 0.0)
    px = image_px / (max(w, h) + 2 * pad)
    img = cv2.resize(img, (max(1, round((w + 2 * pad) * px)), max(1, round((h + 2 * pad) * px))),
                     interpolation=cv2.INTER_AREA)

    def pt(u) -> tuple[int, int]:
        return int((float(u[0]) + pad) * px), int((float(u[1]) + pad) * px)

    cv2.rectangle(img, pt((0, 0)), pt((w, h)), (255, 255, 255), 2)
    if snap.bounds is not None and snap.bounds != (0.0, 0.0, w, h):
        x0, y0, x1, y1 = snap.bounds
        cv2.rectangle(img, pt((x0, y0)), pt((x1, y1)), (0, 140, 255), 2)
    for kind, pos, r in snap.items:
        color = (140, 140, 140) if kind == "obstacle" else (0, 220, 255)
        cv2.circle(img, pt(pos), max(2, int(r * px)), color, 2)
    for body, color, label in ((snap.foe, (40, 40, 230), "GEGNER"), (snap.me, (60, 220, 60), "DU")):
        if not body.present:
            continue
        if body.outline is not None and len(body.outline):
            poly = np.array([pt(p) for p in body.outline], np.int32)
            cv2.polylines(img, [poly], True, color, 2)
        x, y = pt(body.pos)
        org = (x - 20, y - int(body.radius * px) - 6)
        cv2.putText(img, label, org, cv2.FONT_HERSHEY_SIMPLEX, 0.5, (0, 0, 0), 3)
        cv2.putText(img, label, org, cv2.FONT_HERSHEY_SIMPLEX, 0.5, color, 1)
    if snap.me.present and angle is not None:
        tip = snap.me.pos + np.array([math.cos(angle), math.sin(angle)]) * (snap.me.radius + 60)
        cv2.arrowedLine(img, pt(snap.me.pos), pt(tip), (60, 220, 60), 2, tipLength=0.3)
    ok, out = cv2.imencode(".jpg", img, [cv2.IMWRITE_JPEG_QUALITY, 80])
    return base64.b64encode(out.tobytes()).decode() if ok else None


# ---------- Roboter ----------

class Bluetooth:
    """Schickt nur Wechsel: die Firmware hält den letzten Befehl, bis ein neuer kommt."""

    def __init__(self, name: str):
        self.name = name
        self.dry_run = not name
        self.client = None
        self.key = STOP
        self._lock = asyncio.Lock()

    @property
    def state(self) -> str:
        if self.dry_run:
            return "Probelauf"
        return "verbunden" if self.client is not None and self.client.is_connected else "getrennt"

    async def connect(self) -> None:
        if self.dry_run:
            log.info("Probelauf: kein Roboter verbunden, Tasten nur in der Konsole.")
            return
        from bleak import BleakClient, BleakScanner

        log.info("Verbinde Roboter „%s“ …", self.name)
        device = await BleakScanner.find_device_by_filter(lambda d, _ad: d.name == self.name, timeout=10)
        if device is None:
            raise PilotError(f"Roboter „{self.name}“ nicht gefunden. Einschalten, näher an diesen PC "
                             "stellen und den KI-Client neu starten.")
        self.client = BleakClient(device)
        await self.client.connect()
        log.info("Roboter „%s“ verbunden.", self.name)

    async def send(self, key: str, force: bool = False) -> None:
        async with self._lock:
            if key == self.key and not force:
                return
            if self.dry_run:
                log.info("Taste %r", key)
            else:
                if self.client is None or not self.client.is_connected:
                    raise PilotError(f"Bluetooth zu „{self.name}“ getrennt. KI-Client neu starten.")
                await self.client.write_gatt_char(CHAR_UUID, key.encode(), response=True)
            self.key = key

    async def close(self) -> None:
        with contextlib.suppress(Exception):
            await self.send(STOP, force=True)
        if self.client is not None:
            with contextlib.suppress(Exception):
                await self.client.disconnect()


class Heading:
    """Front des eigenen Roboters aus der eigenen Bewegung; die Kamera allein kennt sie nicht."""

    def __init__(self):
        self.angle: float | None = None
        self.key = STOP
        self.since = 0.0

    def update(self, key: str, me: Body, t: float) -> None:
        if key != self.key:
            self.key, self.since = key, t
            if key in ("a", "d"):
                # Drehen auf der Stelle macht jede alte Schätzung wertlos.
                self.angle = None
        speed = float(np.linalg.norm(me.vel))
        if key in ("w", "s") and me.present and speed > MOVE_SPEED and t - self.since >= MEASURE_S:
            angle = math.atan2(float(me.vel[1]), float(me.vel[0]))
            self.angle = angle if key == "w" else _wrap(angle + math.pi)

    def held(self, t: float) -> float:
        return t - self.since


def _wrap(a: float) -> float:
    return (a + math.pi) % (2 * math.pi) - math.pi


def _unit(v: np.ndarray) -> np.ndarray:
    n = float(np.linalg.norm(v))
    return v / n if n > 1e-6 else np.array([1.0, 0.0], np.float32)


class Driver:
    """Fährt eine vom Modell gewählte Taktik 20× pro Sekunde; das Modell selbst ist dafür zu langsam."""

    def __init__(self):
        self.tactic = "hold"
        self.side = 1
        self._pulse: list[tuple[str, float]] = []

    def set(self, tactic: str, side: int) -> None:
        self.tactic, self.side = tactic, side

    def key(self, snap: Snapshot, heading: Heading, t: float) -> str:
        while self._pulse and self._pulse[0][1] <= t:
            self._pulse.pop(0)
        if self._pulse:
            return self._pulse[0][0]
        me, foe = snap.me, snap.foe
        if self.tactic == "hold" or not me.present or snap.bounds is None:
            return STOP
        x0, y0, x1, y1 = snap.bounds
        margin = me.radius + EDGE_MARGIN
        center = np.array([(x0 + x1) / 2, (y0 + y1) / 2], np.float32)
        near_edge = not (x0 + margin < me.pos[0] < x1 - margin and y0 + margin < me.pos[1] < y1 - margin)
        if near_edge:
            # Randschutz geht vor jeder Taktik: eine Kante kostet mehr als ein verpasster Treffer.
            outward = _unit(me.pos - center)
            if heading.angle is not None:
                front = np.array([math.cos(heading.angle), math.sin(heading.angle)])
                if float(front @ outward) > 0.3:
                    return self._start([("s", 0.35)], t)
            target = center
        elif not foe.present and self.tactic != "retreat":
            return STOP
        else:
            target = self._target(snap, center)
        target = np.clip(target, [x0 + margin, y0 + margin], [x1 - margin, y1 - margin])
        if heading.angle is None:
            # Steckt der Roboter fest, zeigt Zurückfahren die Front genauso gut.
            if heading.key == "w" and heading.held(t) > STUCK_S:
                return self._start([("s", 0.4)], t)
            return "w" if heading.key not in ("a", "d") else self._start([("w", 0.4)], t)
        want = math.atan2(float(target[1] - me.pos[1]), float(target[0] - me.pos[0]))
        diff = _wrap(want - heading.angle)
        if abs(diff) < ALIGN:
            return "w"
        # Bildkoordinaten: y zeigt nach unten, positiver Winkel ist im Uhrzeigersinn, also rechts.
        spin = "d" if diff > 0 else "a"
        return self._start([(spin, min(0.6, max(0.1, abs(diff) / SPIN_RATE))), ("w", 0.4)], t)

    def _start(self, steps: list[tuple[str, float]], t: float) -> str:
        self._pulse = []
        for key, dur in steps:
            t += dur
            self._pulse.append((key, t))
        return self._pulse[0][0]

    def _target(self, snap: Snapshot, center: np.ndarray) -> np.ndarray:
        me, foe = snap.me, snap.foe
        gap = me.radius + foe.radius
        away = _unit(me.pos - foe.pos)
        if self.tactic == "push_out":
            out = _unit(foe.pos - center)
            # Erst auf die Mittelseite des Gegners, sonst schiebt man ihn zur Mitte statt hinaus.
            if float((me.pos - foe.pos) @ out) > -foe.radius:
                return foe.pos - out * (gap + 60)
            return foe.pos
        if self.tactic == "flank":
            perp = np.array([-away[1], away[0]]) * self.side
            point = foe.pos + perp * (gap + 80)
            return point if float(np.linalg.norm(point - me.pos)) > 90 else foe.pos
        if self.tactic == "circle":
            a = math.radians(40) * self.side
            rot = np.array([away[0] * math.cos(a) - away[1] * math.sin(a),
                            away[0] * math.sin(a) + away[1] * math.cos(a)])
            return foe.pos + rot * CIRCLE_R
        if self.tactic == "retreat":
            return me.pos + away * 250
        if self.tactic == "dodge":
            return me.pos + np.array([-away[1], away[0]]) * self.side * 200
        return foe.pos


