def copilot_client(token: str | None):
    from copilot import CopilotClient

    # None = OpenAI-Schlüssel: dann darf keine GitHub-Anmeldung dieses PCs mitlaufen.
    return CopilotClient(github_token=token or None, use_logged_in_user=token == "", log_level="warning")


def _ensure_runtime(install=None, tries: int = 3) -> None:
    if os.environ.get("COPILOT_CLI_PATH"):
        return
    if install is None:
        from copilot._cli_download import ensure_runtime_wrapper as install
    for attempt in range(1, tries + 1):
        try:
            install()
            return
        except PermissionError as exc:
            # Der Virenscanner hält frisch entpackte Dateien kurz fest und das SDK benennt ohne
            # Wiederholung um; ein zweiter Versuch ein paar Sekunden später klappt in der Regel.
            if attempt == tries:
                raise PilotError(
                    "Copilot konnte nicht eingerichtet werden (Zugriff verweigert). Kurz warten und neu "
                    "starten; hilft das nicht, %LOCALAPPDATA%\\github-copilot-sdk vom Virenscanner "
                    "ausnehmen.") from exc
            log.warning("Copilot-Installation blockiert (%s), neuer Versuch …", exc)
            time.sleep(3)


# ---------- Einrichtung an der Konsole ----------

async def _probe(token: str, client_factory=copilot_client) -> tuple[str, list[dict]]:
    client = None
    try:
        client = client_factory(token)
        await client.start()
        auth = await client.get_auth_status()
        if not auth.isAuthenticated:
            raise PilotError(auth.statusMessage or "Nicht bei GitHub Copilot angemeldet.")
        models = []
        for m in await client.list_models():
            if m.policy is not None and m.policy.state == "disabled":
                continue
            if not m.capabilities.supports.vision:
                continue
            efforts = m.supported_reasoning_efforts or []
            models.append({"id": m.id, "name": m.name,
                           "multiplier": m.billing.multiplier if m.billing else None,
                           "effort": "low" if "low" in efforts else None})
        return auth.login or "", models
    except PilotError:
        raise
    except Exception as exc:
        raise PilotError(f"Copilot nicht erreichbar: {exc}") from exc
    finally:
        if client is not None:
            with contextlib.suppress(Exception):
                await client.stop()


def _openai_models(key: str) -> list[dict]:
    """Prüft den Schlüssel kostenlos über die Modellliste und liefert die passenden Modelle."""
    req = urllib.request.Request(f"{OPENAI_URL}/models", headers={"Authorization": f"Bearer {key}"})
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            data = json.load(resp)["data"]
    except urllib.error.HTTPError as exc:
        if exc.code == 401:
            raise PilotError("OpenAI lehnt den Schlüssel ab.") from exc
        raise PilotError(f"OpenAI antwortet mit Fehler {exc.code}.") from exc
    except (urllib.error.URLError, TimeoutError) as exc:
        raise PilotError(f"OpenAI nicht erreichbar: {exc}") from exc
    ids = sorted(m["id"] for m in data if OPENAI_MODELS.match(m["id"]) and not OPENAI_SKIP.search(m["id"]))
    return [{"id": i, "name": i, "multiplier": None,
             "effort": "low" if OPENAI_REASONING.match(i) else None} for i in ids]


def _copilot_login() -> tuple[str, list[dict]]:
    token = next((os.environ[k] for k in TOKEN_ENV if os.environ.get(k)), "")
    while True:
        try:
            user, models = asyncio.run(_probe(token))
            break
        except PilotError as exc:
            print(exc)
        print("Entweder auf diesem PC „copilot“ starten und /login ausführen, oder hier ein Token eingeben.")
        token = getpass.getpass("GitHub-Token (github_pat_… oder gho_…; klassische ghp_… gehen nicht, "
                                "leer = abbrechen): ").strip()
        if not token:
            raise PilotError("Ohne Copilot-Anmeldung kann die KI nicht fahren.")
    if not models:
        raise PilotError("Dein Copilot-Zugang bietet kein Modell mit Bildverständnis an.")
    print(f"Bei Copilot angemeldet als {user or 'unbekannt'}.")
    return token, models


def _openai_login() -> tuple[str, list[dict]]:
    key = os.environ.get("OPENAI_API_KEY", "")
    while True:
        if not key:
            key = getpass.getpass("OpenAI-API-Schlüssel (sk-…, von platform.openai.com; leer = abbrechen): "
                                  ).strip()
            if not key:
                raise PilotError("Ohne OpenAI-Schlüssel kann die KI nicht fahren.")
        try:
            models = _openai_models(key)
            break
        except PilotError as exc:
            print(exc)
            key = ""
    if not models:
        raise PilotError("Dein OpenAI-Zugang bietet kein passendes Modell mit Bildverständnis an.")
    print("OpenAI-Schlüssel gilt. Jeder Zug kostet dort Geld (Abrechnung pro Aufruf).")
    return key, models


async def _scan() -> list[str]:
    from bleak import BleakScanner

    devices = await BleakScanner.discover(timeout=5)
    return sorted({d.name for d in devices if d.name and d.name.lower().startswith(ROBOT_PREFIX)})


def _choose(title: str, options: list[str], default: int) -> int:
    print(title)
    for i, text in enumerate(options, 1):
        print(f"  {i}) {text}")
    while True:
        text = input(f"Auswahl [{default + 1}]: ").strip()
        if not text:
            return default
        if text.isdigit() and 1 <= int(text) <= len(options):
            return int(text) - 1
        print(f"Bitte eine Zahl von 1 bis {len(options)} eingeben.")


def setup(cfg: dict) -> Setup:
    """Fragt Zugang, Modell, Steuerung und Roboter ab; die Antworten sind beim nächsten Start Vorgabe."""
    ai = {**DEFAULTS, **cfg.get("ai", {})}
    if ai["access"] not in ACCESSES:
        ai["access"] = "openai" if os.environ.get("OPENAI_API_KEY") else "copilot"
    access = ACCESSES[_choose("Womit soll die KI denken?", [
        "GitHub Copilot – über dein Copilot-Abo",
        "OpenAI – eigener API-Schlüssel (sk-…), Abrechnung pro Aufruf"], ACCESSES.index(ai["access"]))]
    print("Richte die KI ein (beim ersten Mal lädt das Copilot-SDK einige Sekunden nach) …")
    _ensure_runtime()
    token = key = ""
    if access == "copilot":
        token, models = _copilot_login()
    else:
        key, models = _openai_login()

    names = [m["name"] + (f" (×{m['multiplier']:g})" if m["multiplier"] is not None else "") for m in models]
    fallback = next((i for i, m in enumerate(models) if m["id"] == OPENAI_DEFAULT and access == "openai"), 0)
    pick = next((i for i, m in enumerate(models) if m["id"] == ai["model"]), fallback)
    model = models[_choose("Welches Modell soll kämpfen?", names, pick)]

    steering = STEERINGS[_choose("Wie soll es steuern?", [
        "taktik – Modell wählt Taktiken, ein schneller Regler fährt (empfohlen)",
        "direkt – Modell fährt selbst kurze Stücke"], STEERINGS.index(ai["steering"])
        if ai["steering"] in STEERINGS else 0)]

    robot = ""
    while True:
        print("Suche Roboter per Bluetooth …")
        try:
            found = asyncio.run(_scan())
        except Exception as exc:
            print(f"Bluetooth geht auf diesem PC nicht ({exc}). Nur ein Probelauf ist möglich.")
            found = []
        options = [*found, "Erneut suchen", "Probelauf ohne Roboter (Tasten nur in der Konsole)"]
        default = found.index(ai["robot"]) if ai["robot"] in found else (0 if found else len(options) - 1)
        choice = _choose("Welchen Roboter steuert die KI?", options, default)
        if choice < len(found):
            robot = found[choice]
            break
        if choice == len(options) - 1:
            break

    cfg["ai"] = {**ai, "access": access, "model": model["id"], "steering": steering, "robot": robot}
    return Setup(model["id"], model["name"], model["effort"], steering, robot, token,
                 float(ai["turn_s"]), int(ai["max_calls"]), int(ai["image_px"]), key)


# ---------- Kampf ----------

class Pilot:
    def __init__(self, server: str, token: str, slot: int, cfg: Setup, client_factory=copilot_client):
        self.server = server
        self.token = token
        self.slot = slot
        self.cfg = cfg
        self.client_factory = client_factory
        self.state: dict | None = None
        self.received = 0.0
        self.jpeg: bytes | None = None
        self.frame: dict | None = None
        self.status = ""
        self.error: str | None = None
        self.calls = 0
        self.comment = ""
        self.bt = Bluetooth(cfg.robot)
        self.heading = Heading()
        self.driver = Driver()

    def post(self, path: str, data: dict) -> tuple[int, dict]:
        req = urllib.request.Request(f"http://{self.server}{path}", data=json.dumps(data).encode(),
                                     method="POST")
        req.add_header("Content-Type", "application/json")
        req.add_header("Authorization", f"Bearer {self.token}")
        try:
            with urllib.request.urlopen(req, timeout=3.0) as res:
                return res.status, json.loads(res.read())
        except urllib.error.HTTPError as exc:
            try:
                return exc.code, json.loads(exc.read())
            except ValueError:
                return exc.code, {"ok": False, "message": f"Server antwortet mit Fehler {exc.code}."}

    def _status(self, text: str) -> None:
        if text != self.status:
            log.info(text)
            self.status = text

    def public(self) -> dict:
        return {"status": self.status, "model": self.cfg.label, "steering": self.cfg.steering,
                "robot": self.cfg.robot or "Probelauf", "bluetooth": self.bt.state, "calls": self.calls,
                "max_calls": self.cfg.max_calls,
                "tactic": self.driver.tactic if self.cfg.steering == "taktik" else None,
                "key": self.bt.key.strip() or None, "comment": self.comment, "error": self.error}

    def snapshot(self) -> Snapshot:
        return snapshot_from(self.state, self.slot, time.monotonic() - self.received < STALE_S)

    async def main(self) -> None:
        client = None
        tasks: list[asyncio.Task] = []
        try:
            await self.bt.connect()
            self._status("Verbinde KI-Modell …")
            client = self.client_factory(None if self.cfg.api_key else self.cfg.token)
            await client.start()
            tasks = [asyncio.create_task(c) for c in (self._read(), self._watch(), self._think(client),
                                                      self._report())]
            done, _ = await asyncio.wait(tasks, return_when=asyncio.FIRST_EXCEPTION)
            for task in done:
                task.result()
        finally:
            for task in tasks:
                task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)
            await self.bt.close()
            if client is not None:
                with contextlib.suppress(Exception):
                    await client.stop()

    async def _read(self) -> None:
        from websockets.asyncio.client import connect
        from websockets.exceptions import ConnectionClosed, WebSocketException

        url = f"ws://{self.server}/ws?" + urllib.parse.urlencode({"token": self.token, "frames": 1})
        lost = False
        while True:
            try:
                async with connect(url, max_size=None, open_timeout=5) as ws:
                    if lost:
                        log.info("Verbindung zum Server wieder da.")
                        lost = False
                    async for packet in ws:
                        self._take(packet)
            except ConnectionClosed as exc:
                if exc.rcvd is not None and exc.rcvd.code == 4401:
                    raise PilotError("Der Server kennt diese Anmeldung nicht mehr. KI-Client neu starten.") \
                        from exc
            except (OSError, TimeoutError, WebSocketException):
                pass
            if not lost:
                log.warning("Verbindung zum Server %s verloren, versuche weiter …", self.server)
                lost = True
            await asyncio.sleep(1.0)

    def _take(self, packet: bytes) -> None:
        n = int.from_bytes(packet[:4], "little")
        state = json.loads(packet[4:4 + n])
        jpeg = packet[4 + n:]
        if jpeg and state.get("frame"):
            self.jpeg, self.frame = jpeg, state["frame"]
        self.state, self.received = state, time.monotonic()

    async def _watch(self) -> None:
        """Schnelle Schleife: Fahrtrichtung schätzen, Taktik fahren und außerhalb des Kampfs anhalten."""
        battle = None
        while True:
            snap = self.snapshot()
            t = time.monotonic()
            self.heading.update(self.bt.key, snap.me, t)
            if snap.battle != battle:
                battle = snap.battle
                self.driver.set("hold", 1)
            if not snap.fighting:
                await self.bt.send(STOP)
            elif self.cfg.steering == "taktik":
                await self.bt.send(self.driver.key(snap, self.heading, t))
            await asyncio.sleep(WATCH_S)

    async def _report(self) -> None:
        while True:
            try:
                code, _ = await asyncio.to_thread(self.post, "/api/ai_status", {"status": self.public()})
            except (OSError, ValueError):
                code = 0
            if code in (401, 403):
                raise PilotError("Die Moderation hat die KI vom Platz genommen. Zum Weiterspielen den "
                                 "KI-Client neu starten.")
            await asyncio.sleep(STATUS_S)

    async def _think(self, client) -> None:
        session = None
        battle = None
        turns = 0
        try:
            while True:
                snap = self.snapshot()
                if not snap.fighting:
                    self._status("Bereit, wartet auf den Kampf")
                    await asyncio.sleep(0.2)
                    continue
                if snap.battle != battle:
                    battle, self.calls = snap.battle, 0
                    session = await self._drop(session)
                if self.calls >= self.cfg.max_calls:
                    self._status("Anfragelimit für diesen Kampf erreicht")
                    self.driver.set("hold", 1)
                    await asyncio.sleep(0.5)
                    continue
                if session is None or turns >= SESSION_TURNS:
                    await self._drop(session)
                    session = await self._session(client)
                    turns = 0
                self._status("Kämpft")
                started = time.monotonic()
                image = picture(snap, self.jpeg, self.frame, self.heading.angle, self.cfg.image_px)
                attachments = [{"type": "blob", "data": image, "mimeType": "image/jpeg"}] if image else None
                self.calls += 1
                turns += 1
                try:
                    reply = await session.send_and_wait(self.describe(snap), attachments=attachments,
                                                        timeout=TURN_TIMEOUT_S)
                except TimeoutError:
                    log.warning("Modell antwortet nicht rechtzeitig.")
                    with contextlib.suppress(Exception):
                        await session.abort()
                    continue
                except Exception as exc:
                    # Netz- oder Modellfehler: mit frischer Sitzung weiter statt den ganzen Kampf aufzugeben.
                    self.error = f"Modell: {exc}"[:120]
                    log.warning(self.error)
                    session = await self._drop(session)
                    await asyncio.sleep(2.0)
                    continue
                self.error = None
                text = getattr(getattr(reply, "data", None), "content", None) or ""
                if text.strip():
                    self.comment = text.strip()[:200]
                    log.info("Runde %d: %s", self.calls, self.comment)
                await asyncio.sleep(max(0.0, self.cfg.turn_s - (time.monotonic() - started)))
        finally:
            await self._drop(session)

    @staticmethod
    async def _drop(session) -> None:
        if session is not None:
            with contextlib.suppress(Exception):
                await session.disconnect()

    async def _session(self, client):
        from copilot import PermissionHandler, ToolSet

        extra = {"reasoning_effort": self.cfg.effort} if self.cfg.effort else {}
        if self.cfg.api_key:
            extra["provider"] = {"type": "openai", "base_url": OPENAI_URL, "api_key": self.cfg.api_key}
        return await client.create_session(
            on_permission_request=PermissionHandler.approve_all, model=self.cfg.model, tools=self.tools(),
            system_message={"mode": "replace", "content": prompt(self.slot, self.cfg.steering)},
            # Nur die eigenen Werkzeuge: kein Dateizugriff, keine Shell auf dem KI-PC.
            available_tools=ToolSet().add_custom("*"), skip_custom_instructions=True, streaming=False,
            **extra,
        )

    def tools(self) -> list:
        from copilot import define_tool

        async def drive(args: DriveArgs) -> str:
            if not self.snapshot().fighting:
                return "Gerade läuft kein Kampf; die Motoren bleiben aus."
            key = {"forward": "w", "back": "s", "left": "a", "right": "d"}[args.direction]
            await self.bt.send(key)
            end = time.monotonic() + args.ms / 1000
            while time.monotonic() < end and self.snapshot().fighting:
                await asyncio.sleep(WATCH_S)
            await self.bt.send(STOP)
            return "Erledigt. " + self.position(self.snapshot())

        async def stop() -> str:
            await self.bt.send(STOP)
            return "Angehalten."

        async def set_tactic(args: TacticArgs) -> str:
            self.driver.set(args.tactic, 1 if args.side == "right" else -1)
            log.info("Taktik: %s (%s)", args.tactic, args.side)
            return f"Taktik {args.tactic} aktiv."

        async def ulti() -> str:
            code, result = await asyncio.to_thread(self.post, "/api/ulti", {})
            if code != 200:
                return f"Geht nicht: {result.get('message', code)}"
            log.info("Ulti gezündet.")
            return "Ulti gezündet."

        async def say(args: SayArgs) -> str:
            await asyncio.to_thread(self.post, "/api/say", {"text": args.text})
            log.info("Sagt: %s", args.text)
            return "Gesagt."

        common = [
            define_tool("ulti", description="Laser-Ulti auf den Gegner zünden (nur wenn bereit).",
                        handler=ulti, skip_permission=True),
            define_tool("say", description="Sprechblase über deinem Roboter auf der Bühne.", handler=say,
                        skip_permission=True),
        ]
        if self.cfg.steering == "taktik":
            return [define_tool("set_tactic", description="Taktik wählen, die der Regler fährt.",
                                handler=set_tactic, skip_permission=True), *common]
        return [define_tool("drive", description="Kurz fahren oder drehen, danach Stopp.", handler=drive,
                            skip_permission=True),
                define_tool("stop", description="Sofort anhalten.", handler=stop, skip_permission=True),
                *common]

    def position(self, snap: Snapshot) -> str:
        me, foe = snap.me, snap.foe
        if not me.present:
            return "Dein Roboter ist gerade nicht zu sehen."
        text = f"Du bei ({me.pos[0]:.0f}, {me.pos[1]:.0f})"
        if self.heading.angle is not None:
            text += f", Front zeigt {math.degrees(self.heading.angle) % 360:.0f}°"
        if foe.present:
            dist = float(np.linalg.norm(foe.pos - me.pos)) - me.radius - foe.radius
            text += f"; Gegner bei ({foe.pos[0]:.0f}, {foe.pos[1]:.0f}), Lücke {max(0.0, dist):.0f}"
        return text + "."

    def describe(self, snap: Snapshot) -> str:
        me, foe = snap.me, snap.foe
        lines = [f"Kampfzeit {snap.elapsed or 0:.0f} s. Koordinaten in Arena-Einheiten, x nach rechts, "
                 "y nach unten; 0° = rechts, 90° = unten."]
        if snap.size is not None:
            lines.append(f"Arena {snap.size[0]:.0f} × {snap.size[1]:.0f}.")
            if snap.bounds is not None and snap.bounds != (0.0, 0.0, *snap.size):
                x0, y0, x1, y1 = snap.bounds
                lines.append(f"Erlaubte Zone x {x0:.0f}–{x1:.0f}, y {y0:.0f}–{y1:.0f}.")
        lines.append(f"Du: {me.hp:.0f}/{me.max_hp:.0f} HP{', AUSSERHALB!' if me.outside else ''}. "
                     f"Gegner: {foe.hp:.0f}/{foe.max_hp:.0f} HP{', außerhalb' if foe.outside else ''}.")
        unknown = " Fahrtrichtung unbekannt." if self.heading.angle is None else ""
        lines.append(self.position(snap) + unknown)
        lines.append(f"Ulti: {snap.ulti}.")
        if self.cfg.steering == "taktik":
            lines.append(f"Aktuelle Taktik: {self.driver.tactic}.")
        for kind, pos, _r in snap.items:
            label = "Hindernis" if kind == "obstacle" else "Power-up"
            lines.append(f"{label} bei ({pos[0]:.0f}, {pos[1]:.0f}).")
        return "\n".join(lines)


def run(server: str, result: dict, cfg: Setup) -> None:
    """Kämpft, bis Strg+C, Rauswurf oder ein Fehler kommt; danach steht der Roboter."""
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s", datefmt="%H:%M:%S")
    for noisy in ("websockets", "bleak", "copilot"):
        logging.getLogger(noisy).setLevel(logging.WARNING)
    pilot = Pilot(server, result["token"], result["slot"], cfg)
    log.info("KI %s steuert Roboter %d (%s, %s). Beenden mit Strg+C.", cfg.label, result["slot"],
             cfg.robot or "Probelauf", cfg.steering)
    asyncio.run(pilot.main())
